===================================================================
--- agents/chatassist/agent_test.go	
+++ agents/chatassist/agent_test.go	
@@ -1,238 +1,242 @@
 package chatassist

 import (
 	"ai/agents"
 	"ai/board"
 	"ai/rag"
 	"ai/tools"
 	"context"
 	"os"
 	"path/filepath"
 	"strings"
 	"testing"

 	"github.com/alicebob/miniredis/v2"
 )

 // newTestAssistant создаёт ассистента во временной директории без доски и RAG.
 func newTestAssistant(t *testing.T, prompt string) *Assistant {
 	t.Helper()
 	return newAssistant(filepath.Join(t.TempDir(), "proj"), "testproj", prompt, nil, nil)
 }

 // newTestAssistantBoard создаёт ассистента с подключённой in-memory доской.
 // Доску возвращаем для контроля состояния.
 func newTestAssistantBoard(t *testing.T, prompt string) (*Assistant, *board.Store) {
 	t.Helper()
 	srv := miniredis.RunT(t)
 	store := board.NewStoreNoCheck(board.StoreConfig{Addr: srv.Addr(), Project: "testproj"})
 	a := newAssistant(filepath.Join(t.TempDir(), "proj"), "testproj", prompt, store, nil)
 	return a, store
 }

 // fakeAssistantSearcher — управляемая реализация поисковика для тестов без сети.
 type fakeAssistantSearcher struct {
 	results []rag.SearchResult
 	err     error
 	last    rag.SearchParams
 }

 func (f *fakeAssistantSearcher) Ping(context.Context) error { return nil }

 func (f *fakeAssistantSearcher) Search(_ context.Context, p rag.SearchParams) ([]rag.SearchResult, error) {
 	f.last = p
 	return f.results, f.err
 }

+func (f *fakeAssistantSearcher) ProjectInfo(_ context.Context, _ string) (rag.ProjectInfo, error) {
+	return rag.ProjectInfo{}, nil
+}
+
 var _ agents.Agent = (*Assistant)(nil)

 func TestAssistantInterface(t *testing.T) {
 	a := newTestAssistant(t, "что сейчас делает проект?")
 	if len(a.GetSystemMessages(nil)) == 0 {
 		t.Fatal("системный промпт не задан")
 	}
 	um := a.GetUserMessages()
 	if len(um) != 1 || um[0].Type != agents.MessageTypeHuman {
 		t.Fatalf("ожидается один human-промпт с вопросом, получено %+v", um)
 	}
 	if msg, must := a.RequiredToolFirstRound(); must {
 		t.Fatalf("ассистент не обязан вызывать инструмент, got %q", msg)
 	}
 }

 // TestAssistantToolsIncludeBoardWritesAndCodeSearch — набор ассистента содержит
 // чтение файлов, семантический поиск по коду (CodeSearch) и write-инструменты
 // доски (создание эпиков/задач/багов), чтобы ассистент мог действовать по
 // смыслу сообщения. Пишущих файловых инструментов быть не должно (Ф-1).
 func TestAssistantToolsIncludeBoardWritesAndCodeSearch(t *testing.T) {
 	a, _ := newTestAssistantBoard(t, "создай эпик порт на Rust")
 	names := map[string]bool{}
 	for _, td := range a.GetTools() {
 		names[td.Name] = true
 	}
 	for _, w := range []string{
 		"List", "ReadFiles", "ReadMap",
 		tools.CodeSearch,
 		tools.WebSearch,
 		tools.BoardListEpics, tools.BoardGetEpic, tools.BoardListTasks, tools.BoardGetTask,
 		tools.BoardListBugs, tools.BoardGetBug,
 		tools.BoardCreateEpic, tools.BoardUpdateEpic, tools.BoardDeleteEpic, tools.BoardSetEpicStatus,
 		tools.BoardCreateTask, tools.BoardUpdateTask, tools.BoardDeleteTask, tools.BoardSetTaskStatus,
 		tools.BoardCreateBug, tools.BoardSetBugStatus, tools.BoardReviewBug,
 	} {
 		if !names[w] {
 			t.Errorf("ассистент не включает инструмент %q", w)
 		}
 	}
 	// Файлы проекта ассистент не пишет — за разработку отвечают агенты.
 	for _, w := range []string{"WriteFiles", "AppendFile", "DeleteFiles", "Run", "SearchReplace"} {
 		if names[w] {
 			t.Errorf("ассистент не должен включать инструмент %q", w)
 		}
 	}
 }

 // TestAssistantWithoutBoardSkipsBoardTools — без доски (store == nil) Board-инструменты
 // не попадают в набор: их вызов вернул бы «доска не подключена».
 func TestAssistantWithoutBoardSkipsBoardTools(t *testing.T) {
 	a := newTestAssistant(t, "вопрос")
 	names := map[string]bool{}
 	for _, td := range a.GetTools() {
 		names[td.Name] = true
 	}
 	for _, w := range []string{"BoardListEpics", "BoardCreateEpic", "BoardSetTaskStatus"} {
 		if names[w] {
 			t.Errorf("ассистент без доски не должен включать Board-инструмент %q", w)
 		}
 	}
 }

 func TestAssistantCallFunctionRejectsWrite(t *testing.T) {
 	a := newTestAssistant(t, "вопрос")
 	if _, err := a.CallFunction("WriteFiles", nil); err == nil {
 		t.Fatal("попытка вызвать записывающий файл инструмент должна завершиться ошибкой (not in tool set)")
 	}
 }

 func TestAssistantWritesIntoOutputDir(t *testing.T) {
 	// sanity: ассистент остаётся FileOps-агентом, способным читать проект.
 	a := newTestAssistant(t, "покажи структуру")
 	if err := os.WriteFile(filepath.Join(a.OutputDir, "main.go"), []byte("package main\n"), 0o644); err != nil {
 		t.Fatal(err)
 	}
 	out, err := a.CallFunction("List", map[string]any{"path": "."})
 	if err != nil {
 		t.Fatalf("List: %v", err)
 	}
 	if len(out) == 0 {
 		t.Fatal("List не вернул содержимое проекта")
 	}
 }

 // TestAssistantCreatesEpicOnBoardDirectly — ассистент сам выполняет действие на
 // доске через свой набор: BoardCreateEpic доступен и реально создаёт эпик.
 func TestAssistantCreatesEpicOnBoardDirectly(t *testing.T) {
 	a, store := newTestAssistantBoard(t, "создай эпик")
 	out, err := a.CallFunction(tools.BoardCreateEpic, map[string]any{
 		"task_id": "CHAT-01", "title": "Порт на Rust", "description": "перенести сервер",
 		"assigned_role": "Backend Lead",
 	})
 	if err != nil {
 		t.Fatalf("BoardCreateEpic: %v", err)
 	}
 	if !strings.Contains(string(out), "success") {
 		t.Fatalf("ожидался success, got %s", out)
 	}
 	e, err := store.GetEpic(context.Background(), "CHAT-01")
 	if err != nil {
 		t.Fatalf("эпик не на доске: %v", err)
 	}
 	if e.Title != "Порт на Rust" {
 		t.Fatalf("title = %q", e.Title)
 	}
 }

 // TestAssistantSystemMessagesIncludeRAGBlock — при доступном RAG в системный
 // промпт попадает блок «Релевантный код по вопросу» (поиск — по проекту).
 func TestAssistantSystemMessagesIncludeRAGBlock(t *testing.T) {
 	fake := &fakeAssistantSearcher{results: []rag.SearchResult{
 		{File: "server/token.go", StartLine: 1, EndLine: 3, Score: 0.91, Snippet: "package server"},
 	}}
 	a := newAssistant(filepath.Join(t.TempDir(), "proj"), "proj-x", "где валидация токена?", nil, fake)
 	msgs := a.GetSystemMessages(nil)
 	if len(msgs) != 1 {
 		t.Fatalf("ожидался 1 системный промпт, got %d", len(msgs))
 	}
 	if !strings.Contains(msgs[0].Message, "Релевантный код по вопросу") || !strings.Contains(msgs[0].Message, "server/token.go") {
 		t.Fatalf("промпт не содержит RAG-блок:\n%s", msgs[0].Message)
 	}
 	if fake.last.Project != "proj-x" {
 		t.Fatalf("поиск по проекту = %q, ожидался proj-x", fake.last.Project)
 	}
 }

 // TestAssistantSystemMessagesWithoutRAG — nil-клиент RAG (или пустой проект) не
 // ломает ассистента: промпт строится без блока «релевантный код».
 func TestAssistantSystemMessagesWithoutRAG(t *testing.T) {
 	a := newAssistant(filepath.Join(t.TempDir(), "proj"), "proj-x", "где валидация?", nil, nil)
 	msgs := a.GetSystemMessages(nil)
 	if strings.Contains(msgs[0].Message, "Релевантный код по вопросу") {
 		t.Fatalf("без RAG промпт не должен содержать блок:\n%s", msgs[0].Message)
 	}
 	if !strings.Contains(msgs[0].Message, "ассистент") {
 		t.Fatalf("системный промпт ассистента должен сохраниться:\n%s", msgs[0].Message)
 	}
 }

 // TestAssistantPromptHasWebSearchRule — системный промпт содержит правило
 // живой информации: свежие данные (новости/факты/справка/погода) — через
 // WebSearch, degraded — честно ответить из знаний с пометкой «не живые».
 func TestAssistantPromptHasWebSearchRule(t *testing.T) {
 	a := newTestAssistant(t, "какая погода в Москве?")
 	msgs := a.GetSystemMessages(nil)
 	p := msgs[0].Message
 	for _, want := range []string{"WebSearch", "degraded", "не живые", "новости", "погода"} {
 		if !strings.Contains(p, want) {
 			t.Errorf("промпт не содержит %q:\n%s", want, p)
 		}
 	}
 }

 // TestAssistantPromptHasCreationChecklist — при создании эпиков/задач промпт
 // требует собрать СВОДКУ обязательных параметров, при неоднозначности СПРОСИТЬ
 // пользователя (а не угадывать) и вывести пример сводки перед вызовом
 // инструмента; для эпика — решение про «ревью архитектора» и лида направления
 // (Ф-1 PLAN-dashboard-chat-create).
 func TestAssistantPromptHasCreationChecklist(t *testing.T) {
 	a := newTestAssistant(t, "создай эпик на рефакторинг бэкенда")
 	p := a.GetSystemMessages(nil)[0].Message
 	for _, want := range []string{"сводк", "спроси", "ревью архитектора", "BoardCreateEpic", "BoardCreateTask", "Пример сводки"} {
 		if !strings.Contains(p, want) {
 			t.Errorf("промпт не содержит %q:\n%s", want, p)
 		}
 	}
 }

 // TestAssistantRAGBlockSearchParams — блок ищет по проекту, scope пуст (весь
 // проект); ошибка поиска деградирует в пустую строку.
 func TestAssistantRAGBlockSearchParams(t *testing.T) {
 	fake := &fakeAssistantSearcher{results: []rag.SearchResult{{File: "a.go", Snippet: "x"}}}
 	blk := assistantRAGBlock("proj-x", "где токен?", fake)
 	if blk == "" {
 		t.Fatal("блок должен быть непустым")
 	}
 	if fake.last.Scope != "" {
 		t.Fatalf("scope должен быть пустым (весь проект), got %q", fake.last.Scope)
 	}

 	// Ошибка поиска (Qdrant недоступен) → блок пуст (degrade, как планировщик).
 	fail := &fakeAssistantSearcher{err: &rag.UnavailableError{Err: context.Canceled}}
 	if got := assistantRAGBlock("proj-x", "где токен?", fail); got != "" {
 		t.Fatalf("ошибка поиска должна деградировать в пустой блок, got %q", got)
 	}

 	// nil-поисковик → пустой блок.
 	if got := assistantRAGBlock("proj-x", "где токен?", nil); got != "" {
 		t.Fatalf("nil-поисковик должен давать пустой блок, got %q", got)
 	}
 }

Index: rag/client.go
===================================================================
--- rag/client.go	
+++ rag/client.go	
@@ -1,252 +1,253 @@
 // Клиент векторной памяти RAG поверх Qdrant (gRPC, см. PLAN-qdrant.md, Ф-1).
 //
 // Инфраструктурный слой: инициализация клиента и create-if-not-exists
 // коллекции. Размерность векторов определяется пробой модели эмбеддингов
 // (EMBEDDING_MODEL), метрика — косинусная (Distance_Cosine). Qdrant может
 // отсутствовать: соединение ленивое, недоступность всплывает в первом же
 // вызове (Ping / EnsureCollection) и обрабатывается наружу как graceful
 // degrade (инструменты вернут skipped, а не упадут — как ЛСП-серверы).

 package rag

 import (
 	"context"
 	"errors"
 	"fmt"
 	"net"
 	"os"
 	"strconv"
 	"strings"
 	"sync"

 	"ai/logging"

 	"github.com/qdrant/go-client/qdrant"
 )

 // Значения по умолчанию и переменные окружения.
 const (
 	// DefaultAddr — адрес Qdrant gRPC по умолчанию (QDRANT_ADDR).
 	DefaultAddr = "localhost:6334"
 	// DefaultCollectionName — имя коллекции по умолчанию (QDRANT_COLLECTION_NAME).
 	DefaultCollectionName = "project_code_base"
 )

 // probeText — короткий текст для определения размерности модели эмбеддингов
 // (длина вектора известна только самой модели).
 const probeText = "Этот текст проганяется через модель эмбеддингов, чтобы узнать размерность вектора."

 // Config — настройки клиента RAG-памяти. Пустые поля добираются из переменных
 // окружения: QDRANT_ADDR, QDRANT_COLLECTION_NAME, EMBEDDING_MODEL.
 type Config struct {
 	// Addr — адрес Qdrant вида "host:port" (gRPC, порт 6334).
 	Addr string
 	// CollectionName — имя коллекции чанков проекта.
 	CollectionName string
 	// EmbeddingModel — модель эмбеддингов Ollama.
 	EmbeddingModel string
 	// Embedder — источник эмбеддингов; пусто — OllamaEmbedder по умолчанию.
 	Embedder Embedder
 }

 // QdrantStore — минимальный набор операций Qdrant gRPC, используемых RAG.
 // Выделен в интерфейс, чтобы hermetic-тесты работали с fake-реализацией
 // без сети (см. PLAN-qdrant.md, Ф-1: «fake-клиент Qdrant (интерфейс)»).
 type QdrantStore interface {
 	CollectionExists(ctx context.Context, collectionName string) (bool, error)
 	CreateCollection(ctx context.Context, request *qdrant.CreateCollection) error
 	Upsert(ctx context.Context, request *qdrant.UpsertPoints) (*qdrant.UpdateResult, error)
 	Delete(ctx context.Context, request *qdrant.DeletePoints) (*qdrant.UpdateResult, error)
 	Query(ctx context.Context, request *qdrant.QueryPoints) ([]*qdrant.ScoredPoint, error)
+	Count(ctx context.Context, request *qdrant.CountPoints) (*qdrant.CountResponse, error)
 	Close() error
 }

 // Client — единая точка доступа к векторной памяти проекта.
 type Client struct {
 	store      QdrantStore
 	embed      Embedder
 	collection string

 	mu  sync.Mutex
 	dim int // кэш размерности векторов после первого определения
 }

 // Collection возвращает имя коллекции (для логов и фильтров поиска).
 func (c *Client) Collection() string { return c.collection }

 // NewClient создаёт клиент RAG поверх реальных сервисов: Qdrant (gRPC) и
 // эмбеддинги Ollama. Подключение к Qdrant откладывается (grpc.NewClient
 // ленив), поэтому недоступный Qdrant не роняет запуск: ошибка появится при
 // первом же обращении (Ping / EnsureCollection / Search) и обрабатывается
 // как graceful degrade.
 func NewClient(cfg Config) (*Client, error) {
 	if cfg.Embedder == nil {
 		model := cfg.EmbeddingModel
 		if model == "" {
 			model = strings.TrimSpace(os.Getenv("EMBEDDING_MODEL"))
 		}
 		embed, err := NewOllamaEmbedder(model)
 		if err != nil {
 			return nil, err
 		}
 		cfg.Embedder = embed
 	}

 	host, port, err := parseAddr(cfg.Addr)
 	if err != nil {
 		return nil, err
 	}

 	collection := cfg.CollectionName
 	if collection == "" {
 		collection = strings.TrimSpace(os.Getenv("QDRANT_COLLECTION_NAME"))
 	}
 	if collection == "" {
 		collection = DefaultCollectionName
 	}

 	store, err := qdrant.NewClient(&qdrant.Config{
 		Host: host, Port: port,
 		PoolSize:               1,
 		SkipCompatibilityCheck: true, // проверка версии ходит в сеть — не нужна
 	})
 	if err != nil {
 		return nil, fmt.Errorf("rag: создание клиента Qdrant: %w", err)
 	}

 	return &Client{store: store, embed: cfg.Embedder, collection: collection}, nil
 }

 // newClient собирает Client из готовых компонентов. Используется тестами
 // с fake-реализациями QdrantStore/Embedder (hermetic, без сети).
 func newClient(store QdrantStore, embed Embedder, collection string) *Client {
 	return &Client{store: store, embed: embed, collection: collection}
 }

 // NewClientSafe создаёт клиент RAG, но при некорректной конфигурации (битый
 // QDRANT_ADDR/EMBEDDING_MODEL и т.п.) возвращает nil вместо ошибки: клиент
 // опционален (tools.Deps.RAG), инструменты без него просто деградируют в
 // skipped. Само подключение к Qdrant по-прежнему откладывается до первого
 // вызова — недоступный Qdrant на этом этапе не ошибка.
 func NewClientSafe(cfg Config) *Client {
 	c, err := NewClient(cfg)
 	if err != nil {
 		logging.Warnf("rag: клиент RAG не создан (%v) — CodeSearch будет возвращать skipped", err)
 		return nil
 	}
 	return c
 }

 // parseAddr разбирает адрес Qdrant "host:port" из QDRANT_ADDR. Пустая строка —
 // DefaultAddr. Допустим лишний scheme ("http://…") — адрес скопирован с REST-
 // документации, gRPC-порт от этого не меняется.
 func parseAddr(addr string) (host string, port int, err error) {
 	if strings.TrimSpace(addr) == "" {
 		addr = os.Getenv("QDRANT_ADDR")
 	}
 	if strings.TrimSpace(addr) == "" {
 		addr = DefaultAddr
 	}
 	addr = strings.TrimSpace(addr)
 	if i := strings.Index(addr, "://"); i >= 0 {
 		addr = addr[i+3:]
 	}
 	h, p, serr := net.SplitHostPort(addr)
 	if serr != nil {
 		return "", 0, fmt.Errorf("rag: неверный QDRANT_ADDR %q (ожидается host:port): %w", addr, serr)
 	}
 	port, perr := strconv.Atoi(p)
 	if perr != nil || port <= 0 || port > 65535 {
 		return "", 0, fmt.Errorf("rag: неверный порт в QDRANT_ADDR %q: %q", addr, p)
 	}
 	if h == "" {
 		h = "localhost"
 	}
 	return h, port, nil
 }

 // Ping проверяет доступность Qdrant одним лёгким вызовом, не трогая эмбеддер.
 // Инструменты используют его для graceful degrade (skipped), когда Qdrant
 // выключен: падение любых RPC даёт различимую ошибку-подсказку.
 func (c *Client) Ping(ctx context.Context) error {
 	if _, err := c.store.CollectionExists(ctx, c.collection); err != nil {
 		return &UnavailableError{Err: err}
 	}
 	return nil
 }

 // EnsureCollection создаёт коллекцию, если её ещё нет (create-if-not-exists),
 // и возвращает размерность векторов. Размерность определяется пробой модели
 // эмбеддингов и кэшируется. Вызывается при полной индексации и авто-обновлении.
 func (c *Client) EnsureCollection(ctx context.Context) (int, error) {
 	dim, err := c.dimension(ctx)
 	if err != nil {
 		return 0, err
 	}

 	exists, err := c.store.CollectionExists(ctx, c.collection)
 	if err != nil {
 		return dim, &UnavailableError{Err: err}
 	}
 	if exists {
 		return dim, nil
 	}

 	if cerr := c.store.CreateCollection(ctx, &qdrant.CreateCollection{
 		CollectionName: c.collection,
 		VectorsConfig: qdrant.NewVectorsConfig(&qdrant.VectorParams{
 			Size:     uint64(dim),
 			Distance: qdrant.Distance_Cosine,
 		}),
 	}); cerr != nil {
 		// Гонка: коллекцию параллельно создал другой процесс между проверкой
 		// и Create. Повторная проверка отличает её от настоящей ошибки.
 		if ok, okErr := c.store.CollectionExists(ctx, c.collection); okErr == nil && ok {
 			return dim, nil
 		}
 		return dim, fmt.Errorf("rag: не удалось создать коллекцию %s: %w", c.collection, cerr)
 	}

 	return dim, nil
 }

 // dimension определяет (и кэширует) размерность векторов модели эмбеддингов:
 // прогоняет probeText через Embed и замеряет длину вектора.
 func (c *Client) dimension(ctx context.Context) (int, error) {
 	c.mu.Lock()
 	defer c.mu.Unlock()
 	if c.dim != 0 {
 		return c.dim, nil
 	}
 	probe, err := c.embed.Embed(ctx, probeText)
 	if err != nil {
 		return 0, fmt.Errorf("rag: не удалось определить размерность эмбеддингов (%v): проверь EMBEDDING_MODEL и доступность Ollama", err)
 	}
 	if len(probe) == 0 {
 		return 0, fmt.Errorf("rag: модель эмбеддингов вернула пустой вектор")
 	}
 	c.dim = len(probe)
 	return c.dim, nil
 }

 // Close закрывает соединение с Qdrant.
 func (c *Client) Close() error { return c.store.Close() }

 // UnavailableError — признак того, что Qdrant недоступен: инструменты и
 // индексатор превращают его в "skipped" с подсказкой (graceful degrade),
 // не считая это ошибкой шага.
 type UnavailableError struct{ Err error }

 func (e *UnavailableError) Error() string {
 	return fmt.Sprintf("rag: Qdrant недоступен (%v): проверь QDRANT_ADDR и docker compose up qdrant", e.Err)
 }

 // Unwrap возвращает исходную ошибку gRPC.
 func (e *UnavailableError) Unwrap() error { return e.Err }

 // IsUnavailable отличает недоступность Qdrant от прочих ошибок RAG
 // (инструменты переводят её в статус skipped).
 func IsUnavailable(err error) bool {
 	var u *UnavailableError
 	return errors.As(err, &u)
 }

